// Evidence-backed request-path tests for the Pages leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlabx';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Pages paths match the APK evidence', () => {
  test('POST /projects/{projectID}/duplicates hits /projects/{projectID}/duplicates', async () => {
    const url = await captureURL((c) => c.pages.duplicateProject('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}));
    expect(url).toContain('/projects/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/duplicates');
  });

  test('GET /users/{userID}/pages/bio hits /users/{userID}/pages/bio', async () => {
    const url = await captureURL((c) => c.pages.retrieveBio('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'));
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/pages/bio');
  });

  test('GET /users/{userID}/pages/bio/state hits /users/{userID}/pages/bio/state', async () => {
    const url = await captureURL((c) => c.pages.retrieveBioState('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'));
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/pages/bio/state');
  });
});
